class Member(val name: String, var age: Int = 18) {
    init {
        println("Card made for " + name)
    }
}

fun main() {
    val maya = Member("Maya", 30)
    val sam = Member("Sam")
    sam.age = 19
    println(maya.name + " " + maya.age)
    println(sam.name + " " + sam.age)
}

